package com.onecall.archtests;

import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

import com.onecall.core.catalog_order.internal.operationsdraft.CatalogDraftConfiguration;
import com.onecall.core.operations_iam.employeeauthority.EmployeeAuthorityReadPort;
import com.onecall.core.operations_iam.internal.subjectread.OperationsSubjectReadPersistenceConfiguration;
import com.onecall.core.operations_iam.operationscommand.OperationsCatalogDraftCommand;
import java.lang.reflect.Method;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.Map;
import javax.sql.DataSource;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.beans.factory.support.DefaultListableBeanFactory;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.TransactionDefinition;
import org.springframework.transaction.support.TransactionTemplate;

class OperationsCatalogDraftConfigurationTests {
    Object existing(String name, Class<?> parameter, Object argument) throws Exception { Method method = OperationsSubjectReadPersistenceConfiguration.class.getDeclaredMethod(name, parameter); method.setAccessible(true); return method.invoke(new OperationsSubjectReadPersistenceConfiguration(), argument); }
    TransactionTemplate template() { var result = new TransactionTemplate(); result.setPropagationBehavior(TransactionDefinition.PROPAGATION_REQUIRES_NEW); result.setIsolationLevel(TransactionDefinition.ISOLATION_READ_COMMITTED); result.setTimeout(5); return result; }
    OperationsCatalogDraftCommand resolve(TransactionTemplate template, DefaultListableBeanFactory beans) throws Exception { Method method = CatalogDraftConfiguration.class.getDeclaredMethod("operationsCatalogDraftCommand", TransactionTemplate.class, ObjectProvider.class, ObjectProvider.class); method.setAccessible(true); return (OperationsCatalogDraftCommand) method.invoke(new CatalogDraftConfiguration(), template, beans.getBeanProvider(EmployeeAuthorityReadPort.class), beans.getBeanProvider(Class.forName("com.onecall.core.catalog_order.internal.operationsdraft.CatalogDraftRepository"))); }
    DefaultListableBeanFactory beans() throws Exception { var beans = new DefaultListableBeanFactory(); beans.registerSingleton("authority", mock(EmployeeAuthorityReadPort.class)); Class<?> type = Class.forName("com.onecall.core.catalog_order.internal.operationsdraft.CatalogDraftRepository"); beans.registerSingleton("repository", mock(type)); return beans; }
    @Test void reusesExistingWritableTransactionTemplate() throws Exception { DataSource source = mock(DataSource.class); var manager = (DataSourceTransactionManager) existing("operationsSubjectReadCatalogSaleTransactionManager", DataSource.class, source); assertThat(manager.getDataSource()).isSameAs(source); assertThat(manager.isRollbackOnCommitFailure()).isTrue(); var transaction = (TransactionTemplate) existing("operationsSubjectReadCatalogSaleTransactionTemplate", DataSourceTransactionManager.class, manager); assertThat(transaction.getTransactionManager()).isSameAs(manager); assertThat(resolve(transaction, beans())).isNotNull(); }
    @Test void reusesSameSharedDatasourceAndDsl() throws Exception { Class<?> type = Class.forName("com.onecall.core.catalog_order.internal.operationsdraft.JooqCatalogDraftRepository"); var constructor = type.getDeclaredConstructors()[0]; assertThat(constructor.getParameterTypes()).containsExactly(DataSource.class, org.jooq.DSLContext.class); assertThat(constructor.getParameters()[0].getAnnotation(org.springframework.beans.factory.annotation.Qualifier.class).value()).isEqualTo("operationsSubjectReadDataSource"); assertThat(constructor.getParameters()[1].getAnnotation(org.springframework.beans.factory.annotation.Qualifier.class).value()).isEqualTo("operationsSubjectReadDsl"); }
    @Test void preservesExactTransactionAndTimeoutSettings() throws Exception { for (int index = 0; index < 4; index++) { var transaction = template(); switch (index) { case 0 -> transaction.setReadOnly(true); case 1 -> transaction.setPropagationBehavior(TransactionDefinition.PROPAGATION_REQUIRED); case 2 -> transaction.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ); default -> transaction.setTimeout(6); } var beans = beans(); assertThatThrownBy(() -> resolve(transaction, beans)).hasCauseInstanceOf(OperationsCatalogDraftCommand.Failure.class); } }
    @Test void constructsNoSecondPoolCredentialOrRoleFamily() throws Exception { String source = Files.readString(Path.of("src/main/java/com/onecall/core/catalog_order/internal/operationsdraft/CatalogDraftConfiguration.java")); assertThat(source).doesNotContain("Hikari", "new DataSource", "password", "jdbc:", "@Value").contains("operationsSubjectReadCatalogSaleTransactionTemplate", "@Lazy", "@Profile(\"persistence\")"); }
    @Test void resolvesExactlyOneLazyCommandProvider() throws Exception { assertThat(resolve(template(), beans())).isInstanceOf(OperationsCatalogDraftCommand.class); try (var context = new AnnotationConfigApplicationContext()) { context.getEnvironment().setActiveProfiles("persistence"); context.getEnvironment().getPropertySources().addFirst(new org.springframework.core.env.MapPropertySource("enabled", Map.of("onecall.operations-subject-read.enabled", "true"))); context.register(CatalogDraftConfiguration.class); context.refresh(); assertThat(context.containsBeanDefinition("operationsCatalogDraftCommand")).isTrue(); assertThat(context.getBeanFactory().containsSingleton("operationsCatalogDraftCommand")).isFalse(); } }
    @Test void missingAndAmbiguousProvidersFailClosed() throws Exception { for (String missing : List.of("authority", "repository")) { var beans = beans(); beans.destroySingleton(missing); assertThatThrownBy(() -> resolve(template(), beans)).hasCauseInstanceOf(OperationsCatalogDraftCommand.Failure.class); } for (String duplicate : List.of("authority", "repository")) { var beans = beans(); beans.registerSingleton("duplicate", mock(beans.getBean(duplicate).getClass().getInterfaces()[0])); assertThatThrownBy(() -> resolve(template(), beans)).hasCauseInstanceOf(OperationsCatalogDraftCommand.Failure.class); } }
    @Test void unavailableRequiredCapabilitiesFailClosedWithoutFallback() throws Exception { var beans = beans(); beans.destroySingleton("authority"); beans.registerBeanDefinition("authority", org.springframework.beans.factory.support.BeanDefinitionBuilder.genericBeanDefinition(EmployeeAuthorityReadPort.class, () -> { throw new IllegalStateException("PRIVATE"); }).setLazyInit(true).getBeanDefinition()); assertThatThrownBy(() -> resolve(template(), beans)).hasCauseInstanceOf(OperationsCatalogDraftCommand.Failure.class); }
    @Test void defaultAndWebOnlyRuntimeHaveNoDraftWriteBeans() { for (String profile : List.of("default", "web", "persistence")) for (String enabled : List.of("absent", "false", "true")) try (var context = new AnnotationConfigApplicationContext()) { context.getEnvironment().setActiveProfiles(profile); if (!enabled.equals("absent")) context.getEnvironment().getPropertySources().addFirst(new org.springframework.core.env.MapPropertySource("enabled", Map.of("onecall.operations-subject-read.enabled", enabled))); context.register(CatalogDraftConfiguration.class); context.refresh(); assertThat(context.containsBeanDefinition("operationsCatalogDraftCommand")).isEqualTo(profile.equals("persistence") && enabled.equals("true")); assertThat(context.getBeanFactory().containsSingleton("operationsCatalogDraftCommand")).isFalse(); } }
}
